const fs = require('fs');
const path = require('path');

const islamQuestions = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'generators', 'agama_islam.json'), 'utf8'));
const seenQuestions = new Set(islamQuestions.map(q => q.question));

function addQ(grade, difficulty, topic, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate Islam question found: "${question}"`);
  }
  seenQuestions.add(question);

  const diffCode = difficulty === 'mudah' ? 'm' : (difficulty === 'sedang' ? 's' : 'u');
  const index = islamQuestions.filter(q => q.grade === grade && q.difficulty === difficulty).length + 1;
  const id = `aga-islam-k${grade}-${diffCode}${String(index).padStart(2, '0')}`;

  islamQuestions.push({
    id,
    grade,
    subject: 'pendidikan-agama',
    religion: 'islam',
    difficulty,
    topic,
    question,
    options,
    correctAnswer,
    explanation
  });
}

addQ(5, 'mudah', 'Surat At-Tin', 'Surat At-Tin yang berada pada juz 30 Al-Qur\'an terdiri dari ... ayat.', ['6', '7', '8', '9'], 2, 'Surat At-Tin terdiri dari 8 ayat dan termasuk golongan surat Makkiyah.');
addQ(5, 'mudah', 'Asmaul Husna', 'Asmaul Husna Al-Qawiyyu memiliki arti bahwa Allah adalah Maha ...', ['Kuat / Perkasa', 'Bijaksana', 'Lemah Lembut', 'Pengampun'], 0, 'Al-Qawiyyu artinya Yang Maha Kuat dan memiliki kekuatan mutlak tanpa batas.');
addQ(5, 'mudah', 'Asmaul Husna', 'Asmaul Husna Al-Qayyum mengandung arti bahwa Allah Maha ...', ['Mendengar rahasia', 'Mandiri dan senantiasa mengurus makhluk-Nya', 'Menyiksa orang zalim', 'Mencatat amal'], 1, 'Al-Qayyum artinya Yang Maha Mandiri dan berdiri sendiri tanpa bergantung pada makhluk.');
addQ(5, 'mudah', 'Asmaul Husna', 'Asmaul Husna Al-Muhyi artinya Allah adalah Dzat yang Maha ...', ['Menghidupkan segala makhluk', 'Mematikan', 'Membangkitkan', 'Membinasakan'], 0, 'Al-Muhyi artinya Yang Maha Menghidupkan seluruh ciptaan di alam semesta.');
addQ(5, 'mudah', 'Asmaul Husna', 'Asmaul Husna Al-Mumit memiliki makna bahwa Allah Maha ...', ['Mematikan', 'Merajai', 'Melihat', 'Menghitung'], 0, 'Al-Mumit artinya Yang Maha Mematikan semua yang bernyawa bila ajalnya tiba.');
addQ(5, 'mudah', 'Asmaul Husna', 'Asmaul Husna Al-Ba\'its artinya Allah adalah Dzat yang Maha ...', ['Membagi rezeki', 'Membangkitkan manusia dari alam kubur', 'Menciptakan malaikat', 'Menghias surga'], 1, 'Al-Ba\'its artinya Yang Maha Membangkitkan manusia kembali setelah kematian.');
addQ(5, 'mudah', 'Rukun Iman Rasul', 'Beriman kepada rasul-rasul utusan Allah SWT merupakan rukun iman yang ke- ...', ['2', '3', '4', '5'], 2, 'Urutan rukun iman: Iman kepada Allah, Malaikat, Kitab, Rasul, Hari Kiamat, Qadha & Qadar.');
addQ(5, 'mudah', 'Makanan Halal', 'Makanan yang dinyatakan halal dalam syariat Islam adalah makanan yang ...', ['Rasanya manis dan enak', 'Boleh dikonsumsi serta memenuhi kriteria syariat Islam', 'Harganya sangat mahal', 'Berasal dari luar negeri'], 1, 'Halal berarti diizinkan oleh hukum syara\' untuk dikonsumsi.');
addQ(5, 'mudah', 'Minuman Haram', 'Minuman memabukkan yang merusak akal sehat dan diharamkan secara tegas dalam Al-Qur\'an adalah ...', ['Susu murni', 'Khamr (minuman beralkohol)', 'Jus buah anggur segar', 'Madu hutan'], 1, 'Khamr diharamkan karena memabukkan dan menghilangkan kesadaran akal sehat.');
addQ(5, 'mudah', 'Kisah Nabi', 'Nabi yang diutus kepada kaum Bani Israil dan diberi mukjizat menyembuhkan orang buta serta kusta adalah Nabi ...', ['Nabi Zakaria a.s.', 'Nabi Isa a.s.', 'Nabi Yahya a.s.', 'Nabi Sulaiman a.s.'], 1, 'Nabi Isa a.s. diberi mukjizat menyembuhkan penyakit dan menghidupkan orang mati atas izin Allah.');

addQ(5, 'sedang', 'Surat At-Tin Hakikat', 'Dalam Surat At-Tin ayat ke-4, Allah menegaskan bahwa manusia diciptakan dalam bentuk ...', ['Paling lemah tak berdaya', 'Sebaik-baik bentuk (Ahsani Taqwim)', 'Sama persis dengan rupa malaikat', 'Paling menyeramkan'], 1, 'Ahsani Taqwim berarti sebaik-baik ciptaan baik secara fisik proporsional maupun anugerah akal budi.');
addQ(5, 'sedang', 'Fathu Makkah', 'Peristiwa pembebasan kota Makkah oleh Rasulullah SAW bersama sepuluh ribu kaum muslimin pada tahun 8 Hijriyah dinamakan peristiwa ...', ['Perang Badar', 'Fathu Makkah', 'Perjanjian Hudaibiyah', 'Bai\'at Aqabah'], 1, 'Fathu Makkah adalah peristiwa kemenangan agung pembebasan kota Makkah secara damai.');
addQ(5, 'sedang', 'Akhlak Nabi Fathu Makkah', 'Sikap mulia yang ditunjukkan Nabi Muhammad SAW kepada tokoh-tokoh kafir Quraisy saat Fathu Makkah adalah ...', ['Memenjarakan mereka di benteng gurun', 'Memberikan pengampunan umum (amnesti) dan tidak membalas dendam masa lalu', 'Merampas seluruh rumah dan toko milik mereka', 'Mengusir seluruh keluarga Quraisy ke luar jazirah Arab'], 1, 'Nabi meneladankan pemaafan tanpa dendam: "Pergilah kalian, sesungguhnya kalian adalah orang-orang yang bebas."');
addQ(5, 'sedang', 'Kisah Nabi Ilyas', 'Nabi Ilyas a.s. diutus oleh Allah SWT untuk memberantas kemusyrikan kaumnya yang menyembah berhala bernama ...', ['Latta', 'Ba\'al', '\'Uzza', 'Manat'], 1, 'Kaum Nabi Ilyas di daerah Ba\'labak menyembah patung berhala bernama Ba\'al.');
addQ(5, 'sedang', 'Kisah Nabi Ilyasa', 'Nabi yang diangkat oleh Allah untuk melanjutkan dakwah Nabi Ilyas a.s. dan senantiasa sabar memimpin umatnya adalah Nabi ...', ['Nabi Yunus a.s.', 'Nabi Ilyasa a.s.', 'Nabi Syu\'aib a.s.', 'Nabi Dzulkifli a.s.'], 1, 'Nabi Ilyasa a.s. adalah anak angkat dan penerus perjuangan dakwah Nabi Ilyas a.s.');
addQ(5, 'sedang', 'Nisab Zakat Emas', 'Nisab kepemilikan emas simpanan yang wajib dikeluarkan zakat malnya setelah berlalu satu tahun (haul) adalah seberat ...', ['50 gram', '85 gram emas murni', '100 gram', '125 gram'], 1, 'Nisab emas murni adalah 20 dinar atau setara dengan 85 gram emas.');
addQ(5, 'sedang', 'Persentase Zakat Mal', 'Kadar persentase zakat mal yang wajib dikeluarkan dari harta perniagaan atau emas yang telah cukup nisab dan haulnya adalah ...', ['1%', '2,5%', '5%', '10%'], 1, 'Kadar zakat mal (emas, perak, dan perniagaan) adalah 2,5%.');
addQ(5, 'sedang', 'Bangkai Halal', 'Dua jenis bangkai binatang yang dihalalkan untuk dimakan oleh umat Islam berdasarkan sabda Nabi adalah ...', ['Bangkai ayam dan sapi', 'Bangkai ikan laut/sungai dan belalang', 'Bangkai kambing dan kelinci', 'Bangkai burung merpati dan bebek'], 1, 'Hadits Nabi: "Dihalalkan bagi kita dua bangkai dan dua darah: bangkai ikan dan belalang, serta hati dan limpa."');
addQ(5, 'sedang', 'Darah Hewan', 'Darah yang mengalir dari leher binatang sembelihan hukumnya untuk dikonsumsi adalah ...', ['Halal dan berkah', 'Haram dan bernajis', 'Makruh jika sedikit', 'Mubah bila dimasak matang'], 1, 'Al-Qur\'an secara tegas mengharamkan darah yang mengalir (damman masfuhan).');
addQ(5, 'sedang', 'Larangan Perundungan', 'Perilaku mengejek fisik teman atau melakukan perundungan (bullying) melanggar ajaran Islam dalam Surat Al-Hujurat karena ...', ['Membakar kalori tubuh berlebihan', 'Dilarang merendahkan dan memperolok kaum yang boleh jadi lebih mulia di sisi Allah', 'Hanya boleh dilakukan kepada musuh negara', 'Dapat membuat seragam sekolah cepat kusut'], 1, 'Al-Hujurat ayat 11 melarang saling mencela atau memanggil dengan panggilan buruk.');
addQ(5, 'sedang', 'Sikap Tasamuh', 'Sikap toleran, lapang dada, dan saling menghormati perbedaan pendapat yang tidak melanggar syariat disebut ...', ['Takabur', 'Tasamuh', 'Tasyrik', 'Ta\'ashub'], 1, 'Tasamuh adalah sikap toleransi dan kelapangan dada dalam berinteraksi sosial.');
addQ(5, 'sedang', 'Shalat Witir', 'Shalat sunnah yang memiliki jumlah rakaat ganjil (1 atau 3 rakaat) sebagai penutup shalat malam disebut shalat ...', ['Tahajud', 'Witir', 'Hajat', 'Istisqa'], 1, 'Shalat Witir artinya ganjil, disunnahkan sebagai penutup rangkaian shalat sunnah malam hari.');
addQ(5, 'sedang', 'Syarat Sembelihan Halal', 'Agar daging hewan sembelihan (seperti kambing atau sapi) halal dimakan, syarat penyembelihan wajib menyebut ...', ['Nama juru masak', 'Kalimat Basmalah / Nama Allah SWT', 'Nama pembeli daging', 'Mantra pengusir darah'], 1, 'Menyebut asma Allah (Basmalah) adalah syarat sah dan mutlak halalnya hewan sembelihan.');
addQ(5, 'sedang', 'Gelar Ulul Azmi', 'Para nabi dan rasul yang memiliki ketabahan, kesabaran, dan keteguhan hati yang luar biasa menghadapi ujian risalah bergelar ...', ['Khulafaur Rasyidin', 'Ulul Azmi', 'Ahlul Bait', 'Assabiqunal Awwalun'], 1, 'Ulul Azmi adalah gelar bagi rasul-rasul yang memiliki ketabahan dan keteguhan luar biasa.');
addQ(5, 'sedang', 'Jumlah Rasul Ulul Azmi', 'Jumlah nabi dan rasul yang mendapatkan kehormatan gelar Ulul Azmi ada ... orang.', ['3 orang', '5 orang (Nabi Nuh, Ibrahim, Musa, Isa, Muhammad)', '7 orang', '10 orang'], 1, 'Lima rasul Ulul Azmi disingkat NIMIM: Nuh, Ibrahim, Musa, Isa, dan Muhammad SAW.');
addQ(5, 'sedang', 'Sifat Syaja\'ah', 'Sikap berani membela kebenaran, menolak ajakan curang, dan membela teman yang dizalimi disebut sikap ...', ['Jubun', 'Syaja\'ah', 'Ananiah', 'Ghadab'], 1, 'Syaja\'ah adalah keberanian moral membela kebenaran demi mencari ridha Allah.');
addQ(5, 'sedang', 'Hewan Air', 'Hewan yang seluruh siklus hidupnya berada di dalam air (seperti ikan tenggiri, lobster, dan udang) hukum dikonsumsi adalah ...', ['Haram mutlak', 'Halal dan suci', 'Makruh jika berukuran kecil', 'Hanya halal jika disembelih lehernya'], 1, 'Rasulullah bersabda tentang air laut: "Airnya suci dan bangkainya halal dimakan."');
addQ(5, 'sedang', 'Halal Zat vs Perolehan', 'Sepotong roti gandum yang lezat namun didapat dari hasil mencuri di warung tetangga dihukumi ...', ['Halal zatnya tetapi haram cara perolehannya (haram lighairihi)', 'Halal sepenuhnya karena asalnya gandum', 'Mubah asalkan dimakan saat lapar sekali', 'Makruh saja'], 0, 'Makanan halal bisa berubah menjadi haram lighairihi apabila diperoleh melalui cara batil seperti mencuri atau korupsi.');
addQ(5, 'sedang', 'Menjaga Sumpah', 'Bersumpah palsu dengan mengatasnamakan Allah demi memenangkan suatu perkara hukum termasuk dosa ...', ['Kecil yang dimaafkan', 'Besar (Al-Yaminul Ghamus)', 'Mubah bagi seorang pedagang', 'Makruh'], 1, 'Sumpah palsu (al-yaminul ghamus) adalah dosa besar yang menenggelamkan pelakunya ke dalam neraka.');
addQ(5, 'sedang', 'Zakat Perdagangan', 'Perhitungan zakat perniagaan dikeluarkan setahun sekali apabila nilai modal dan keuntungannya telah mencapai senilai ...', ['10 gram emas', '85 gram emas murni', '500 kg beras', '1.000 liter minyak goreng'], 1, 'Nisab zakat perniagaan disetarakan dengan nisab zakat emas yaitu senilai 85 gram emas.');

addQ(5, 'sulit', 'Tafsir Asfala Saafiliin', 'Dalam Surat At-Tin ayat ke-5 dinyatakan "Tsumma radadnaahu asfala saafiliin" (kemudian Kami kembalikan dia ke tempat yang serendah-rendahnya). Siapakah golongan manusia yang dimasukkan ke tempat paling hina tersebut?', ['Orang yang mengalami sakit fisik menua', 'Orang yang tidak beriman dan tidak beramal shalih sehingga perilakunya lebih rendah dari hewan', 'Orang yang tidak memiliki rumah bertingkat', 'Orang yang miskin harta di dunia'], 1, 'Manusia yang menyia-nyiakan akal, kafir, dan berbuat maksiat akan dicampakkan ke derajat paling hina di neraka.');
addQ(5, 'sulit', 'Analisis Fathu Makkah', 'Mengapa tindakan Rasulullah SAW memaafkan kaum kafir Quraisy pada peristiwa Fathu Makkah dianggap sebagai puncak keagungan akhlak Islam?', ['Karena beliau tidak memiliki persenjataan yang cukup', 'Karena Rasulullah membuktikan bahwa kemenangan sejati bukanlah membalas dendam melainkan memenangkan hati manusia dengan kasih sayang dan hidayah', 'Karena penduduk Makkah menyerahkan seluruh tambang emas mereka', 'Supaya kaum muslimin bisa segera berdagang'], 1, 'Rasulullah mengajarkan bahwa kekuasaan sejati digunakan untuk menebar rahmat, toleransi, dan pemaafan agung.');
addQ(5, 'sulit', 'Konsep Halalan Thayyiban', 'Al-Qur\'an memerintahkan manusia memakan makanan yang "Halalan Thayyiban". Makna dari kata Thayyib dalam konteks gizi dan kesehatan adalah ...', ['Harganya paling mahal di pasaran', 'Bersih, sehat, bergizi, higienis, dan tidak menimbulkan penyakit bagi tubuh', 'Makanan impor yang sedang viral', 'Makanan olahan cepat saji kalengan'], 1, 'Thayyib berarti baik mutunya, bergizi, bermanfaat bagi stamina tubuh, dan tidak membahayakan kesehatan.');
addQ(5, 'sulit', 'Filosofi Khamr Ummul Khabits', 'Mengapa Rasulullah SAW menjuluki khamr (minuman keras) sebagai "Ummul Khaba-its" (induk segala kejahatan)?', ['Karena harganya sangat murah meriah', 'Karena hilangnya akal sehat akibat khamr memicu terjadinya dosa-dosa besar lain seperti membunuh, berzina, dan kekerasan', 'Karena khamr berwarna merah menyala', 'Karena khamr hanya disukai oleh orang tua'], 1, 'Ketika akal hilang terkendali racun alkohol, seseorang kehilangan kendali nurani dan mudah melakukan berbagai kejahatan brutal.');
addQ(5, 'sulit', 'Karakteristik Ulul Azmi', 'Di antara ribuan nabi dan rasul, mengapa Nabi Nuh, Ibrahim, Musa, Isa, dan Muhammad SAW dikelompokkan ke dalam Ulul Azmi?', ['Karena mereka hidup ribuan tahun', 'Karena menghadapi ujian dan penentangan dakwah yang luar biasa dahsyat namun dihadapi dengan ketabahan serta kesabaran puncak tanpa keluh kesah', 'Karena mereka memiliki kekayaan melimpah', 'Karena kitab suci mereka semuanya berukuran tebal'], 1, 'Ulul Azmi memiliki keteguhan tekad \'azm dan kesabaran tiada tara dalam menghadapi rintangan kaumnya.');
addQ(5, 'sulit', 'Etika Musyawarah Surat Ali Imran', 'Dalam Surat Ali Imran ayat 159, setelah bermusyawarah dan mengambil suatu keputusan bersama, langkah berikutnya yang diperintahkan Allah adalah ...', ['Memperdebatkan kembali hasil mufakat tersebut', 'Bertawakal sepenuhnya kepada Allah dengan tekad melaksanakan keputusan tersebut', 'Menyerahkan beban pelaksanaan kepada ketua kelas saja', 'Membatalkan keputusan jika ada satu orang yang tidak suka'], 1, 'Ayat menegaskan: "Maka apabila engkau telah membulatkan tekad, bertawakallah kepada Allah. Sesungguhnya Allah mencintai orang yang bertawakal."');
addQ(5, 'sulit', 'Analisis Daging Babi', 'Mengapa Islam secara tegas mengharamkan konsumsi daging babi dalam Surat Al-Baqarah ayat 173?', ['Karena babi memiliki taring yang tajam', 'Sebagai bentuk ketaatan mutlak pada larangan Allah (ta\'abbudi) dan babi mengandung najis \'ain serta cacing pita yang berbahaya bagi kesehatan jasmani dan rohani', 'Karena babi tidak mau memakan rumput hijau', 'Supaya peternak babi beralih menjual kambing'], 1, 'Keharaman babi berdimensi taat pada wahyu Allah dan terbukti ilmiah membawa parasit serta racun bagi metabolisme tubuh.');
addQ(5, 'sulit', 'Kajian Sifat Al-Muhyi Al-Mumit', 'Bagaimana seorang siswa kelas 5 merenungi Asmaul Husna Al-Muhyi dan Al-Mumit dalam menata kehidupannya?', ['Merasa tidak perlu menjaga kesehatan karena umur sudah pasti', 'Memanfaatkan setiap detik kehidupan yang Allah berikan untuk beramal kebajikan sebelum datangnya kematian yang pasti', 'Menyendiri di tempat sepi karena takut mati', 'Menolak meminum obat saat terserang penyakit'], 1, 'Kesadaran bahwa Allah yang menghidupkan dan mematikan memotivasi manusia mengisi waktu hidup dengan amal shalih berharga.');
addQ(5, 'sulit', 'Kisah Dakwah Nabi Ilyas', 'Pelajaran berharga dari kegigihan Nabi Ilyas a.s. dalam mendakwahi kaum Ba\'al yang dilanda bencana kemarau panjang adalah ...', ['Kekeringan alam terjadi akibat kemusyrikan dan maksiat, serta keselamatan hanya bisa diraih melalui taubat nasuha kepada Allah', 'Manusia boleh menyembah patung saat musim hujan', 'Kemarau panjang bisa diselesaikan dengan sihir dukun', 'Bencana alam tidak ada kaitannya dengan perilaku moral manusia'], 0, 'Kisah Nabi Ilyas mengingatkan bahwa krisis ekologis seringkali merupakan teguran atas penyimpangan spiritual manusia.');
addQ(5, 'sulit', 'Menyikapi Sikap Takabur', 'Iblis terusir dari surga dan dikutuk Allah hingga hari kiamat bukan karena bodoh, melainkan karena memiliki penyakit hati ...', ['Sifat kikir', 'Sombong (takabur) menolak sujud hormat kepada Nabi Adam a.s. karena merasa dirinya lebih mulia diciptakan dari api', 'Kurang pandai beribadah', 'Tidak bisa berbicara bahasa malaikat'], 1, 'Takabur adalah menolak kebenaran dan meremehkan orang lain, yang menjadi sebab utama jatuhnya Iblis.');
addQ(5, 'sulit', 'Analisis Syarat Halal Makanan', 'Sebuah restoran menyajikan menu ayam goreng renyah yang dimasak menggunakan minyak goreng yang tercampur sedikit lemak babi. Bagaimana hukum memakan ayam tersebut?', ['Halal karena daging asalnya adalah ayam', 'Haram dimakan karena telah terkontaminasi oleh najis mutawassithah / zat haram babi', 'Makruh bila ayamnya berukuran kecil', 'Halal jika dimakan bersama cabai pedas'], 1, 'Percampuran dengan unsur babi yang najis \'ain menjadikan seluruh makanan tersebut terkontaminasi haram.');
addQ(5, 'sulit', 'Makna Al-Qayyum Terhadap Kemandirian', 'Bagaimana cara meneladani Asmaul Husna Al-Qayyum dalam lingkungan sekolah dan rumah?', ['Selalu menyuruh pembantu rumah tangga mengerjakan pekerjaan rumah kita', 'Belajar mandiri, merapikan perlengkapan sekolah sendiri, dan tidak bergantung manja pada orang lain', 'Menolak bekerja sama dengan kelompok belajar', 'Menutup diri dari pergaulan sosial'], 1, 'Meneladani Al-Qayyum tercermin dalam sifat mandiri, tangguh, dan tidak membebani orang lain untuk hal-hal yang mampu dikerjakan sendiri.');
addQ(5, 'sulit', 'Ujian Nabi Musa dalam Ulul Azmi', 'Ketabahan Nabi Musa a.s. yang menjadikannya rasul Ulul Azmi teruji ketika beliau harus menghadapi kediktatoran penguasa tiran yaitu ...', ['Raja Namrud', 'Raja Fir\'aun yang mengaku sebagai tuhan', 'Raja Abrahah', 'Kaisar Heraklius'], 1, 'Nabi Musa dengan sabar menghadapi teror kekejaman Fir\'aun yang menindas kaum Bani Israil.');
addQ(5, 'sulit', 'Menilai Tindakan Bullying', 'Andi melihat temannya yang pendiam sering dipalak uang jajannya oleh kakak kelas. Tindakan syaja\'ah yang tepat dilakukan Andi adalah ...', ['Ikut menertawakan teman tersebut agar tidak ikut dimusuhi', 'Melaporkan tindakan perundungan tersebut dengan berani dan santun kepada guru BP atau wali kelas', 'Merekam kejadian itu untuk diunggah ke TikTok pribadi', 'Menjauhi teman tersebut agar tidak tertular masalah'], 1, 'Syaja\'ah bukan berarti berkelahi sembarangan, melainkan berani mengambil tindakan benar melindungi korban kezaliman lewat pihak berwenang.');
addQ(5, 'sulit', 'Hukum Memakan Hewan Bertaring Buas', 'Rasulullah SAW melarang umat Islam memakan setiap binatang buas yang bertaring (seperti harimau, singa, dan serigala) serta setiap burung yang ...', ['Bisa terbang tinggi di awan', 'Memiliki cakar tajam untuk memangsa (seperti elang dan rajawali)', 'Bertelur lebih dari tiga butir', 'Memiliki warna bulu yang indah'], 1, 'Hadits shahih mengharamkan binatang buas bertaring dan burung bercakar pemangsa karena memiliki tabiat ganas yang mempengaruhi jiwa.');
addQ(5, 'sulit', 'Hikmah Zakat Mal Bagi Perekonomian', 'Mengapa zakat mal memiliki peran penting dalam mencegah penumpukan harta di kalangan orang-orang kaya saja?', ['Agar orang miskin tidak perlu lagi bekerja selamanya', 'Supaya terjadi perputaran ekonomi yang adil dan mempersempit jurang kesenjangan sosial kemiskinan', 'Supaya harga barang dagangan di pasar melambung tinggi', 'Agar pemerintah tidak perlu memungut pajak'], 1, 'Al-Qur\'an menegaskan zakat mencegah agar kekayaan tidak hanya beredar di kalangan orang-orang kaya saja (Surat Al-Hasyr: 7).');
addQ(5, 'sulit', 'Peristiwa Baitul Maqdis dan Isra Mi\'raj', 'Sebelum Nabi Muhammad SAW naik ke Sidratul Muntaha dalam peristiwa Mi\'raj, perjalanan malam (Isra\') ditempuh dari Masjidil Haram di Makkah menuju ...', ['Masjid Nabawi di Madinah', 'Masjidil Aqsha di Baitul Maqdis (Palestina)', 'Masjid Quba', 'Masjid Bir Ali'], 1, 'Isra adalah perjalanan malam dari Masjidil Haram ke Masjidil Aqsha, sebelum dilanjutkan Mi\'raj ke langit ketujuh.');
addQ(5, 'sulit', 'Menjaga Kebersihan Makanan', 'Islam menganjurkan menutup bejana air dan wadah makanan di malam hari. Hikmah ilmiah dan syar\'i anjuran ini adalah ...', ['Supaya makanan tidak dihabiskan oleh kucing tetangga', 'Menjaga makanan dari kuman penyakit, serangga berbahaya, dan debu kotor', 'Supaya aroma masakan tidak tercium orang lain', 'Hanya tradisi suku padang pasir zaman kuno'], 1, 'Menutup wadah makanan adalah sunnah kesehatan pencegahan wabah penyakit (preventive medicine).');
addQ(5, 'sulit', 'Sikap Murid Terhadap Perbedaan', 'Ketika berdiskusi tentang madzhab atau perbedaan furu\'iyyah (cabang ibadah sunnah) di kelas, sikap bijak yang diajarkan Islam adalah ...', ['Mengkafirkan teman yang berbeda gerakan sunnahnya', 'Saling menghormati pendapat fiqih para ulama muktabar dan menjaga kerukunan ukhuwah', 'Memaksa semua orang mengikuti buku catatan kita', 'Mogok belajar bersama'], 1, 'Perbedaan dalam ranah ijtihad fiqih cabang adalah rahmat dan disikapi dengan tasamuh serta saling menghormati.');
addQ(5, 'sulit', 'Analisis Makanan Bangkai Darurat', 'Dalam keadaan darurat kelaparan di tengah hutan rimba dan tidak ada makanan halal sama sekali, seseorang diperbolehkan memakan sedikit bangkai binatang dengan syarat ...', ['Dimakan dengan rasa bangga dan kenyang', 'Sekadar untuk mempertahankan hidup agar tidak mati lemas tanpa melampaui batas', 'Membawanya pulang sebagai oleh-oleh keluarga', 'Mengunggah fotonya ke media sosial'], 1, 'Kaidah fiqih: "Ad-dharuuratu tubiihul mahdzuraat" (Keadaan darurat membolehkan hal terlarang) sebatas menyelamatkan nyawa.');
addQ(5, 'sulit', 'Kajian Surat At-Tin Bukti Sejarah', 'Dalam Surat At-Tin, Allah bersumpah demi "Thur Sina" (Bukit Sinai) dan "Baladil Amin" (Kota yang Aman). Kota yang aman yang dimaksud dalam ayat tersebut adalah ...', ['Kota Yerusalem', 'Kota Makkah Al-Mukarramah', 'Kota Madinah Al-Munawwarah', 'Kota Kairo'], 1, 'Al-Balad Al-Amin merujuk pada kota suci Makkah yang diberi rasa aman dan keberkahan oleh Allah.');
addQ(5, 'sulit', 'Bahaya Sifat Dengki Terhadap Kebaikan', 'Rasulullah SAW bersabda bahwa sifat hasad (dengki) itu memakan amal kebaikan manusia laksana ...', ['Air membasahi kapas yang kering', 'Api memakan kayu bakar hingga habis menjadi abu', 'Matahari mencairkan es batu', 'Angin menerbangkan layang-layang'], 1, 'Hasad melenyapkan timbangan pahala amal kebaikan secara cepat bagai kobaran api membakar tumpukan kayu kering.');
addQ(5, 'sulit', 'Kisah Nabi Isa Ulul Azmi', 'Nabi Isa a.s. dimasukkan ke dalam rasul Ulul Azmi karena ketabahannya saat dikhianati dan hendak disalib oleh musuh-musuhnya, lalu Allah menyelamatkannya dengan cara ...', ['Membuatnya bisa terbang ke luar angkasa', 'Mengangkat beliau ke haribaan-Nya dan menyerupakan wajah orang yang berkhianat (Yudas Iskariot)', 'Membuat musuh-musuhnya tertidur seribu tahun', 'Menenggelamkan kota Yerusalem ke dalam laut'], 1, 'Al-Qur\'an menegaskan Nabi Isa tidak disalib dan tidak dibunuh, melainkan diselamatkan dan diangkat oleh Allah SWT.');
addQ(5, 'sulit', 'Etika Berpakaian Islami', 'Kriteria utama pakaian yang menutup aurat bagi seorang muslim dan muslimah menurut syariat adalah ...', ['Pakaian dari merek terkenal dunia', 'Menutup aurat dengan sempurna, tidak ketat memperlihatkan lekuk tubuh, dan tidak transparan tembus pandang', 'Berwarna hitam pekat dari kepala sampai kaki', 'Hanya boleh dipakai saat berada di dalam masjid'], 1, 'Busana muslim menuntut penutupan aurat yang sopan, longgar, tidak transparan, dan tidak menyerupai lawan jenis.');
addQ(5, 'sulit', 'Hikmah Ibadah Qurban Idul Adha', 'Bagaimana ibadah penyembelihan kurban Idul Adha mendidik jiwa sosial seorang muslim?', ['Melatih kita pamer hewan kurban paling gemuk di hadapan tetangga', 'Mengikis sifat kikir dan egoisme materi dengan membagikan kebahagiaan daging segar kepada kaum miskin', 'Membuat harga daging ternak melonjak tajam', 'Mewajibkan anak-anak berpuasa tiga hari penuh'], 1, 'Qurban mengajarkan pengorbanan harta terbaik demi taqarrub ilallah dan merajut jaring solidaritas kaum dhuafa.');
addQ(5, 'sulit', 'Sikap Mengakui Kesalahan Teman', 'Bila kita melihat sahabat kita berbuat kekeliruan secara tidak sengaja di depan umum, cara menasihati yang meneladani adab Islami adalah ...', ['Menegurnya dengan berteriak keras mempermalukannya di depan orang banyak', 'Menasihatinya secara pribadi empat mata dengan tutur kata santun penuh kasih sayang', 'Menyebarkan foto kekeliruannya di status Instagram', 'Memusuhi sahabat tersebut tanpa penjelasan'], 1, 'Imam Syafi\'i berpesan: menasihati saudara di depan umum adalah mencela, sedangkan menasihati secara empat mata adalah nasihat tulus.');
addQ(5, 'sulit', 'Kajian Asmaul Husna Al-Ba\'its Hari Kebangkitan', 'Mengapa keyakinan terhadap sifat Allah Al-Ba\'its membuat seorang muslim tidak berani berbuat curang saat sendirian?', ['Karena takut tertabrak kendaraan bermotor', 'Karena yakin seluruh jasad dan perbuatannya akan dibangkitkan kembali dari alam kubur untuk dimintai pertanggungjawaban di hadapan Mahkamah Ilahi', 'Karena ingin mendapat hadiah piala kejujuran', 'Karena merasa lelah memikirkan kecurangan'], 1, 'Iman kepada Al-Ba\'its menumbuhkan rasa tanggung jawab eskatologis bahwa tidak ada satu pun dosa yang terkubur tanpa balasan.');
addQ(5, 'sulit', 'Hukum Makanan Mengandung Racun', 'Makanan yang asalnya halal (seperti jamur liar) tetapi terbukti mengandung racun mematikan hukum mengonsumsinya berubah menjadi ...', ['Mubah jika dimasak dengan garam', 'Haram karena syariat Islam melarang manusia menjatuhkan diri ke dalam kebinasaan / bahaya', 'Makruh jika dimakan sedikit saja', 'Sunnah untuk menguji kekebalan tubuh'], 1, 'Kaidah syariat: "Laa dharara wa laa dhiraar" (Tidak boleh membahayakan diri sendiri maupun orang lain).');
addQ(5, 'sulit', 'Pemberantasan Diskriminasi Rasial', 'Dalam Khutbah Haji Wada\', Rasulullah SAW menegaskan prinsip kesetaraan manusia bahwa ...', ['Bangsa Arab lebih mulia derajatnya dari bangsa Ajam (non-Arab)', 'Tidak ada kelebihan orang Arab atas non-Arab, kulit putih atas kulit hitam, kecuali atas dasar ketakwaan kepada Allah', 'Kaum bangsawan harus diberi perlakuan hukum istimewa', 'Orang miskin tidak berhak memimpin negara'], 1, 'Islam meruntuhkan rasisme: tolok ukur kemuliaan manusia semata-mata adalah takwa dan amal shalih (Surat Al-Hujurat: 13).');
addQ(5, 'sulit', 'Makna Tawadhu dalam Prestasi', 'Ketika memperoleh nilai ujian tertinggi se-kecamatan, bagaimana seorang siswa kelas 5 mengamalkan ajaran tawadhu?', ['Mengunggah sertifikat dengan kata-kata meremehkan peserta lain', 'Mengucapkan syukur kepada Allah, berterima kasih kepada guru dan orang tua, serta bersedia membantu teman yang kesulitan belajar', 'Menolak berbicara dengan teman yang nilainya rendah', 'Menuntut kepala sekolah memberi uang pembinaan tunai'], 1, 'Prestasi yang dibarengi ketawadhuan melipatgandakan keberkahan ilmu dan kemuliaan akhlak.');

addQ(6, 'mudah', 'Surat Al-Kafirun', 'Surat Al-Kafirun yang memuat prinsip toleransi beragama terdiri dari ... ayat.', ['4', '5', '6', '7'], 2, 'Surat Al-Kafirun terdiri dari 6 ayat dan tergolong surat Makkiyah.');
addQ(6, 'mudah', 'Rukun Iman Kiamat', 'Meyakini dengan sepenuh hati akan datangnya Hari Kiamat merupakan rukun iman yang ke- ...', ['3', '4', '5', '6'], 2, 'Iman kepada Hari Akhir (Kiamat) adalah rukun iman yang ke-5.');
addQ(6, 'mudah', 'Rukun Iman Qadha Qadar', 'Iman kepada Qadha dan Qadar (takdir Allah) merupakan rukun iman yang ke- ...', ['4', '5', '6', '1'], 2, 'Iman kepada Qadha dan Qadar adalah rukun iman ke-6.');
addQ(6, 'mudah', 'Kiamat Sugra', 'Kematian seorang manusia atau terjadinya musibah banjir setempat dinamakan kiamat ...', ['Sugra (Kiamat Kecil)', 'Kubra (Kiamat Besar)', 'Mutlak', 'Hakiki'], 0, 'Kiamat Sugra adalah kiamat kecil seperti kematian individu atau bencana alam lokal.');
addQ(6, 'mudah', 'Kiamat Kubra', 'Peristiwa hancurnya seluruh alam semesta, bintang-bintang berjatuhan, dan bumi memuntahkan isinya disebut kiamat ...', ['Sugra', 'Kubra (Kiamat Besar)', 'Samawi', 'Aradhi'], 1, 'Kiamat Kubra adalah kehancuran total seluruh jagat raya.');
addQ(6, 'mudah', 'Ibadah Haji', 'Rukun Islam yang kelima yaitu menunaikan ibadah haji ke Baitullah bagi yang ...', ['Memiliki pakaian bagus', 'Mampu (istitha\'ah) baik fisik, materi, maupun perjalanan', 'Telah berusia lanjut', 'Berasal dari suku Quraisy'], 1, 'Ibadah haji diwajibkan sekali seumur hidup bagi mereka yang mampu (istitha\'ah).');
addQ(6, 'mudah', 'Tawaf', 'Gerakan mengelilingi Ka\'bah sebanyak 7 kali putaran berlawanan arah putaran jarum jam disebut ...', ['Sa\'i', 'Tawaf', 'Wukuf', 'Tahallul'], 1, 'Tawaf adalah ibadah mengitari Ka\'bah sebanyak 7 putaran diawali dari Hajar Aswad.');
addQ(6, 'mudah', 'Sa\'i', 'Berlari-lari kecil bolak-balik sebanyak 7 kali antara bukit Safa dan bukit Marwah dinamakan ibadah ...', ['Tawaf', 'Sa\'i', 'Mabit', 'Jumrah'], 1, 'Sa\'i meneladani perjuangan Siti Hajar mencari sumber air antara bukit Safa dan Marwah.');
addQ(6, 'mudah', 'Asmaul Husna', 'Asmaul Husna Al-Ghaffar memiliki arti bahwa Allah adalah Maha ...', ['Melihat', 'Pengampun', 'Kaya Raya', 'Pemaksa'], 1, 'Al-Ghaffar bermakna Allah Maha Pengampun terhadap segala dosa hamba yang bertaubat.');
addQ(6, 'mudah', 'Asmaul Husna', 'Asmaul Husna Ash-Shamad artinya Allah adalah tempat seluruh makhluk ...', ['Bersembunyi', 'Meminta dan bergantung', 'Mencari harta emas', 'Bercanda'], 1, 'Ash-Shamad artinya Maha Dibutuhkan dan tempat seluruh alam semesta bergantung.');

addQ(6, 'sedang', 'Surat Al-Kafirun Inti', 'Arti dari ayat terakhir Surat Al-Kafirun "Lakum diinukum wa liya diin" adalah ...', ['"Sesungguhnya manusia dalam kerugian"', '"Untukmu agamamu, dan untukku agamaku"', '"Pertolongan Allah telah datang"', '"Tahukah kamu orang yang mendustakan agama"'], 1, '"Lakum diinukum wa liya diin" menegaskan batasan tegas bahwa masing-masing menjalankan keyakinan tanpa kompromi aqidah.');
addQ(6, 'sedang', 'Yaumul Ba\'ats', 'Hari dibangkitkannya seluruh manusia dari dalam alam kubur setelah tiupan sangkakala kedua dinamakan Yaumul ...', ['Hisab', 'Ba\'ats', 'Mizan', 'Jaza\''], 1, 'Yaumul Ba\'ats adalah hari kebangkitan umat manusia dari alam kubur.');
addQ(6, 'sedang', 'Yaumul Mahsyar', 'Padang yang sangat luas tempat dikumpulkannya seluruh manusia dari umat pertama hingga terakhir untuk menunggu pengadilan Ilahi disebut Padang ...', ['Arafah', 'Mahsyar', 'Sahara', 'Jabal Rahmah'], 1, 'Padang Mahsyar adalah tempat berkumpulnya manusia di akhirat dalam keadaan cemas menunggu hisab.');
addQ(6, 'sedang', 'Yaumul Mizan', 'Hari penimbangan amal kebajikan dan keburukan manusia dengan neraca keadilan Allah yang amat teliti dinamakan Yaumul ...', ['Mizan', 'Hisab', 'Fashl', 'Taghabun'], 0, 'Yaumul Mizan adalah hari penimbangan seluruh catatan amal manusia.');
addQ(6, 'sedang', 'Yaumul Hisab', 'Hari perhitungan dan pemeriksaan seluruh perbuatan yang dikerjakan manusia semasa di dunia dinamakan Yaumul ...', ['Ba\'ats', 'Hisab', 'Barzakh', 'Nusyur'], 1, 'Yaumul Hisab adalah hari perhitungan amal perbuatan tanpa ada yang terlewat sedikit pun.');
addQ(6, 'sedang', 'Sikap Husnuzan', 'Sikap selalu berbaik sangka kepada Allah SWT dan sesama manusia dalam ajaran Islam dinamakan ...', ['Suuzan', 'Husnuzan', 'Ghibah', 'Namimah'], 1, 'Husnuzan adalah berbaik sangka, sedangkan suuzan adalah berburuk sangka.');
addQ(6, 'sedang', 'Larangan Suuzan', 'Mencari-cari kesalahan orang lain (tajassus) dan menuduh tanpa bukti yang jelas merupakan wujud dari sikap ...', ['Husnuzan', 'Suuzan', 'Tawakal', 'Isti\'anah'], 1, 'Suuzan mendorong kecurigaan negatif dan fitnah yang merusak ukhuwah.');
addQ(6, 'sedang', 'Wukuf di Arafah', 'Puncak ibadah haji yang merupakan rukun paling utama dan dilaksanakan pada tanggal 9 Dzulhijjah adalah ...', ['Tawaf Ifadhah', 'Wukuf di Padang Arafah', 'Melempar Jumrah Aqabah', 'Mabit di Mina'], 1, 'Rasulullah SAW bersabda: "Al-Hajju \'Arafah" (Inti ibadah haji adalah wukuf di Arafah).');
addQ(6, 'sedang', 'Pakaian Ihram Pria', 'Pakaian ihram bagi jamaah haji laki-laki terdiri dari ...', ['Jas putih berkancing emas', 'Dua helai kain putih tanpa jahitan (satu untuk selendang, satu untuk sarung)', 'Jubah sutera bersulam benang perak', 'Celana panjang putih dan sorban hijau'], 1, 'Pakaian ihram pria berupa dua helai kain putih tak berjahit sebagai lambang kesetaraan manusia.');
addQ(6, 'sedang', 'Pengertian Qadha', 'Ketetapan atau rencana Allah SWT atas segala sesuatu sejak zaman azali sebelum terciptanya alam semesta disebut ...', ['Qadha', 'Qadar', 'Nasib', 'Kutukan'], 0, 'Qadha adalah kehendak dan ketetapan Allah sejak zaman azali.');
addQ(6, 'sedang', 'Pengertian Qadar', 'Perwujudan nyata atau terjadinya ketetapan Allah atas makhluk-Nya pada waktu dan ukuran tertentu disebut ...', ['Qadha', 'Qadar (Takdir)', 'Ikhtiar', 'Khayal'], 1, 'Qadar adalah realisasi pelaksanaan qadha Allah di alam nyata.');
addQ(6, 'sedang', 'Takdir Mu\'allaq', 'Takdir Allah yang erat kaitannya dengan usaha, ikhtiar, dan doa manusia (seperti kepandaian dan kesehatan) disebut takdir ...', ['Mubram', 'Mu\'allaq', 'Mutlak', 'Bathi'], 1, 'Takdir mu\'allaq adalah takdir yang dapat dipengaruhi oleh ikhtiar sungguh-sungguh dan doa manusia.');
addQ(6, 'sedang', 'Takdir Mubram', 'Takdir Allah yang bersifat pasti, mutlak, dan tidak dapat diubah oleh usaha manusia (seperti ajal kematian dan jenis kelamin kelahiran) disebut takdir ...', ['Mu\'allaq', 'Mubram', 'Ikhtiyari', 'Majazi'], 1, 'Takdir mubram adalah ketetapan paten Allah yang tidak dapat ditawar oleh ikhtiar manusia.');
addQ(6, 'sedang', 'Khutbah Wada\'', 'Khutbah perpisahan yang disampaikan oleh Nabi Muhammad SAW di hadapan ratusan ribu kaum muslimin di Padang Arafah dinamakan Khutbah ...', ['Khutbah Badar', 'Khutbah Wada\'', 'Khutbah Uhud', 'Khutbah Tabuk'], 1, 'Khutbah Wada\' disampaikan pada pelaksanaan Haji Perpisahan (Haji Wada\') tahun 10 H.');
addQ(6, 'sedang', 'Moderasi Wasathiyah', 'Prinsip mengamalkan ajaran agama secara seimbang, adil, toleran, dan tidak bersikap ekstrem dinamakan ...', ['Wasathiyah (Moderasi Beragama)', 'Radikalisme', 'Sekularisme', 'Fanatisme buta'], 0, 'Islam wasathiyah adalah jalan tengah yang adil, toleran, dan menolak ekstremisme.');
addQ(6, 'sedang', 'Tahallul', 'Memotong atau mencukur sebagian rambut kepala sebagai tanda telah berakhirnya larangan-larangan ihram haji dinamakan ...', ['Tahallul', 'Tawaf Wada\'', 'Dam haji', 'Miqat zamani'], 0, 'Tahallul adalah mencukur minimal tiga helai rambut untuk melepaskan diri dari keadaan ihram.');
addQ(6, 'sedang', 'Kisah Ibunda Siti Maryam', 'Ibunda Nabi Isa a.s. yang diabadikan namanya menjadi nama surat dalam Al-Qur\'an atas kesucian dan keteguhan imannya bernama Siti ...', ['Aisyah', 'Maryam', 'Khadijah', 'Asiyah'], 1, 'Siti Maryam adalah wanita suci ibunda Nabi Isa a.s. yang melahirkan tanpa campur tangan laki-laki atas mukjizat Allah.');
addQ(6, 'sedang', 'Toleransi Akidah', 'Ketika tokoh kafir Quraisy mengajak Nabi Muhammad SAW bertukar giliran ibadah (menyembah tuhan berhala setahun lalu menyembah Allah setahun), sikap Nabi berdasarkan Surat Al-Kafirun adalah ...', ['Menerima tawaran tersebut demi kedamaian bisnis', 'Menolak secara tegas karena akidah tauhid tidak boleh dicampuradukkan dengan kemusyrikan', 'Meminta waktu berpikir selama sepuluh tahun', 'Mengikuti separuh syarat mereka'], 1, 'Surat Al-Kafirun turun menolak tegas usulan kompromi sinkretisme ibadah.');
addQ(6, 'sedang', 'Asmaul Husna Al-Afuww', 'Asmaul Husna Al-\'Afuww memiliki arti bahwa Allah Maha ...', ['Pemaaf yang menghapus dosa hingga ke bekas-bekasnya', 'Melihat bintang di langit', 'Menghitung butiran pasir', 'Menyiksa orang lemah'], 0, 'Al-\'Afuww melampaui sekadar ampunan (Al-Ghafur), yakni menghapus catatan dosa hingga tak berbekas.');
addQ(6, 'sedang', 'Jembatan Shirathal Mustaqim', 'Titihan jembatan yang membentang di atas api neraka Jahannam yang akan dilewati oleh seluruh manusia menuju surga dinamakan ...', ['Shirathal Mustaqim', 'Jabal Uhud', 'Maqam Ibrahim', 'Baitul Maqdis'], 0, 'Shirath adalah jembatan akhirat yang kecepatan menyeberangnya tergantung amal perbuatan manusia di dunia.');

addQ(6, 'sulit', 'Tafsir Al-Kafirun Batasan Toleransi', 'Bagaimana konsep toleransi yang benar menurut ajaran Surat Al-Kafirun dalam konteks kehidupan berbangsa di Indonesia?', ['Ikut serta dalam upacara ritual keagamaan umat lain di dalam tempat ibadahnya', 'Bekerja sama secara harmonis dalam bidang sosial, kemanusiaan, dan kemasyarakatan tanpa mencampuradukkan ritual ibadah dan akidah', 'Melarang umat agama lain merayakan hari rayanya di rumah mereka', 'Menyamakan semua tata cara ibadah menjadi satu aliran tunggal'], 1, 'Toleransi Islam berada di ranah sosial (muamalah) dan kemanusiaan dengan saling menghormati, bukan sinkretisme ritual akidah.');
addQ(6, 'sulit', 'Korelasi Ikhtiar Doa Tawakal', 'Bagaimana hubungan yang benar antara ikhtiar maksimal, doa yang khusyuk, dan tawakal dalam menghadapi takdir mu\'allaq (seperti meraih cita-cita)?', ['Cukup berdoa di kamar tidur tanpa perlu belajar dan berusaha', 'Berikhtiar sekuat tenaga dengan belajar tekun, memohon pertolongan lewat doa, lalu memasrahkan hasil akhirnya dengan ridha kepada ketentuan Allah', 'Hanya mengandalkan kepandaian otak sendiri tanpa perlu berdoa kepada Allah', 'Pasrah total sejak awal tanpa mau berbuat apa-apa'], 1, 'Sinergi ikhtiar, doa, dan tawakal adalah pilar tauhid yang kokoh dalam mewujudkan takdir mu\'allaq.');
addQ(6, 'sulit', 'Filosofi Kain Ihram Putih', 'Mengapa jamaah haji dari berbagai penjuru dunia wajib menanggalkan pakaian kebesaran dan mengenakan dua lembar kain ihram putih yang sama saat berhaji?', ['Supaya menghemat biaya pembuatan seragam', 'Melambangkan bahwa di hadapan Allah seluruh manusia setara martabatnya tanpa sekat kasta, harta, ras, dan pangkat kekuasaan duniawi', 'Agar para jamaah tidak kepanasan di padang pasir', 'Hanya peraturan tambahan maskapai penerbangan'], 1, 'Kain ihram putih polos menyimbolkan kafan kematian, kepolosan jiwa, dan kesetaraan mutlak hamba di hadapan Sang Pencipta.');
addQ(6, 'sulit', 'Analisis Yaumul Mizan Terhadap Integritas', 'Bagaimana keyakinan terhadap Yaumul Mizan (hari penimbangan amal) membentuk karakter integritas seorang siswa saat mengerjakan ulangan tanpa diawasi guru?', ['Ia akan menyontek cepat-cepat mumpung guru keluar kelas', 'Ia tetap jujur dan menolak mencontek karena sadar bahwa sekecil apa pun perbuatan curang atau jujur akan ditimbang di neraca keadilan Allah', 'Ia akan memberitahu kunci jawaban kepada seluruh teman sekelas', 'Ia merasa bahwa ujian sekolah tidak ada hubungannya dengan akhirat'], 1, 'Iman pada mizan menanamkan muraqabah bahwa kebaikan seberat dzarrah pun akan dihitung dan dibalas Allah.');
addQ(6, 'sulit', 'Pesan Piagam Khutbah Wada\'', 'Salah satu pesan agung Rasulullah SAW dalam Khutbah Wada\' yang berkaitan erat dengan penegakan Hak Asasi Manusia (HAM) universal adalah ...', ['Perintah untuk menyerang negara-negara tetangga', 'Penegasan bahwa darah, harta, dan kehormatan setiap manusia adalah suci dan haram ditumpahkan atau dirampas secara zalim', 'Kewajiban membayar upeti tahunan kepada pemimpin Makkah', 'Larangan bagi wanita untuk keluar rumah selamanya'], 1, 'Khutbah Wada\' meletakkan deklarasi HAM universal pertama yang melindungi kesucian jiwa, harta, dan kehormatan manusia.');
addQ(6, 'sulit', 'Tanda-Tanda Kiamat Kubra', 'Di antara tanda-tanda besar (kiamat kubra) yang disebutkan dalam hadits shahih adalah terbitnya matahari dari sebelah ...', ['Timur seperti biasa', 'Barat, keluarnya Dajjal, dan turunnya Nabi Isa a.s.', 'Utara dengan sangat lambat', 'Selatan pada musim kemarau'], 1, 'Matahari terbit dari barat merupakan pertanda ditutupnya pintu taubat bagi seluruh umat manusia menjelang kiamat kubra.');
addQ(6, 'sulit', 'Hikmah Mengingat Hari Kiamat', 'Apa manfaat psikologis dan spiritual bagi seorang muslim yang senantiasa mengingat kepastian terjadinya Hari Kiamat?', ['Menjadi pribadi yang putus asa dan tidak mau bekerja lagi', 'Memiliki kendali moral diri (self-restraint), tidak terlena kenikmatan fana dunia, dan terpacu memperbanyak bekal kebajikan', 'Menjual seluruh rumah dan tinggal di dalam gua', 'Merasa takut berlebihan sehingga enggan berteman'], 1, 'Mengingat akhirat memberikan arah tujuan hidup yang bermakna dan menjaga hati dari keserakahan dunia.');
addQ(6, 'sulit', 'Konsep Qadha dan Qadar', 'Seorang pengendara motor melajukan kendaraannya dengan ugal-ugalan tanpa helm hingga menabrak pohon. Ketika ditanya, ia berdalih "Ini sudah takdir Allah". Bagaimana pandangan Islam terhadap alasan orang tersebut?', ['Alasannya sangat benar dan tidak boleh disalahkan', 'Keliru besar, karena ia telah melanggar perintah syariat untuk menjaga keselamatan dan menzalimi dirinya sendiri akibat kelalaian ikhtiarnya', 'Sangat bijaksana karena selalu mengingat takdir', 'Pohon tersebut yang harus dihukum oleh polisi'], 1, 'Menyandarkan kecerobohan diri pada takdir adalah kebodohan; manusia diberi akal dan kebebasan ikhtiar untuk memilih jalan selamat.');
addQ(6, 'sulit', 'Analisis Wukuf Arafah', 'Mengapa wukuf di Padang Arafah pada tanggal 9 Dzulhijjah menjadi rukun yang tidak boleh dilewatkan sama sekali oleh setiap jamaah haji?', ['Karena di Arafah dibagikan makanan gratis paling banyak', 'Karena wukuf adalah miniatur berkumpulnya manusia di Padang Mahsyar untuk bermunajat, bertaubat, dan mengenal hakikat jati diri di hadapan Allah', 'Agar jamaah bisa berfoto bersama di atas bukit batu', 'Hanya syarat seremonial pariwisata Makkah'], 1, 'Wukuf melambangkan perenungan eksistensi manusia (ma\'rifah) dan taubat akbar menyongsong pengadilan Ilahi.');
addQ(6, 'sulit', 'Etika Wasathiyah Melawan Ekstremisme', 'Bagaimana prinsip Islam Wasathiyah membentengi generasi muda dari bahaya paham radikalisme dan terorisme?', ['Dengan mengajarkan sikap apatis dan tidak peduli pada agama', 'Dengan mengedepankan pemahaman agama yang mendalam, berakhlak mulia, mengedepankan perdamaian, dan menolak kekerasan atas nama agama', 'Dengan menghapus pelajaran agama dari kurikulum sekolah', 'Dengan memusuhi semua orang yang taat beribadah'], 1, 'Wasathiyah menekankan rahmah, hikmah, dialog santun, dan menolak kekerasan ekstrim atas nama kesucian agama.');
addQ(6, 'sulit', 'Perbedaan Haji dan Umrah', 'Manakah di bawah ini yang membedakan rukun ibadah haji dengan ibadah umrah?', ['Umrah memiliki rukun wukuf di Arafah, haji tidak ada', 'Haji memiliki rukun wukuf di Arafah dan terikat waktu tertentu (Dzulhijjah), sedangkan umrah tidak ada wukuf dan bisa dikerjakan kapan saja sepanjang tahun', 'Umrah wajib menyembelih seekor unta besar', 'Haji tidak memerlukan pakaian ihram'], 1, 'Inti pembeda haji dan umrah adalah pelaksanaan wukuf di Arafah serta ketentuan waktu (miqat zamani).');
addQ(6, 'sulit', 'Perlindungan Terhadap Hak Dhuafa', 'Dalam hadits Nabi bersabda: "Carilah keridhaan-Ku melalui orang-orang lemah (dhuafa) di antara kalian". Makna hadits ini adalah ...', ['Orang dhuafa tidak perlu diajak shalat berjamaah', 'Keberkahan, pertolongan, dan rezeki suatu bangsa sangat ditentukan oleh sejauh mana mereka memuliakan, melindungi, dan menyejahterakan kaum fakir miskin', 'Orang kaya harus menjauh dari perkampungan dhuafa', 'Kaum dhuafa adalah beban yang merugikan perekonomian negara'], 1, 'Kemuliaan suatu peradaban diukur dari komitmennya membela dan mengangkat harkat hidup kaum marjinal / dhuafa.');
addQ(6, 'sulit', 'Menyikapi Takdir Kehilangan', 'Ketika keluarga Ridwan ditimpa musibah kebakaran rumah yang melenyapkan seluruh harta benda, sikap iman sejati yang ditunjukkan keluarga Ridwan adalah ...', ['Mengutuk takdir dan berhenti menunaikan shalat', 'Bersabar, mengucapkan istirja\' (Inna lillahi...), meyakini ada hikmah besar di balik ujian, dan berikhtiar bangkit kembali', 'Menyalahkan tetangga sebelah tanpa bukti', 'Mencuri harta orang lain untuk mengganti kerugian'], 1, 'Sabar dan ridha atas musibah diiringi ikhtiar bangkit membuktikan kematangan tauhid seorang mukmin.');
addQ(6, 'sulit', 'Makna As-Shamad Tempat Bergantung', 'Jika seorang muslim memahami hakikat Asmaul Husna Ash-Shamad, ke manakah ia pertama kali mengadukan keluh kesah dan memohon pertolongan saat ditimpa kesulitan hidup?', ['Ke dukun atau orang pintar terdekat', 'Hanya bersujud dan memohon pertolongan kepada Allah SWT Sang Maha Pengatur alam', 'Membuat status kemarahan di media sosial sepanjang hari', 'Meminjam uang kepada rentenir yang mengenakan bunga tinggi'], 1, 'Ash-Shamad mendidik jiwa agar tidak bergantung pada makhluk dan memusatkan permohonan hajat hanya kepada Allah.');
addQ(6, 'sulit', 'Kajian Yaumul Jaza\'', 'Setelah melalui hisab dan mizan, manusia akan menerima balasan atas seluruh perbuatannya yang dinamakan Yaumul Jaza\'. Balasan bagi orang beriman dan beramal shalih adalah ...', ['Tidur nyenyak selamanya tanpa bangun', 'Kenikmatan abadi di dalam Surga yang mengalir di bawahnya sungai-sungai dan ridha Allah', 'Dilahirkan kembali ke bumi menjadi orang kaya raya', 'Menjadi penguasa bintang di angkasa luar'], 1, 'Surga (Jannah) adalah tempat balasan abadi penuh kenikmatan lahir batin bagi hamba-hamba Allah yang bertakwa.');
addQ(6, 'sulit', 'Hakikat Persaudaraan Insaniyah', 'Selain ukhuwah Islamiyah (persaudaraan seagama), Islam juga mengajarkan Ukhuwah Insaniyah / Basyariyah, yang berarti ...', ['Persaudaraan sesama pemeluk agama Islam di satu kota', 'Persaudaraan sesama umat manusia sedunia sebagai keturunan Nabi Adam a.s. yang wajib saling menghormati hak hidupnya', 'Persaudaraan antar anggota keluarga sekandung saja', 'Persaudaraan sesama kelompok organisasi politik'], 1, 'Ukhuwah Insaniyah adalah persaudaraan kemanusiaan universal tanpa membedakan warna kulit, bangsa, dan agama.');
addQ(6, 'sulit', 'Menghindari Sikap Riya\' dan Sum\'ah', 'Perilaku menceritakan amal sedekah atau tahajud yang telah dilakukan kepada orang lain agar namanya dipuji dan dikagumi dinamakan penyakit ...', ['Tawadhu', 'Sum\'ah', 'Qana\'ah', 'Zuhud'], 1, 'Sum\'ah adalah memperdengarkan atau membicarakan amal ibadah pribadi kepada orang lain demi meraih sanjungan.');
addQ(6, 'sulit', 'Analisis Makanan Thayyib di Sekolah', 'Mengapa membeli makanan jajanan yang mengandung zat pewarna tekstil berbahaya dan pengawet boraks dilarang dalam ajaran Islam meskipun penjualnya beragama Islam?', ['Karena harganya terlalu murah meriah', 'Karena zat tersebut beracun dan merusak kesehatan organ tubuh, melanggar prinsip "Thayyib" yang diwajibkan syariat', 'Supaya pedagang tersebut bangkrut', 'Hanya aturan tambahan dari dinas kebersihan'], 1, 'Islam mewajibkan konsumsi makanan yang thayyib (sehat dan aman); zat beracun haram dikonsumsi karena merusak tubuh.');
addQ(6, 'sulit', 'Kematangan Beragama di Era Digital', 'Bagaimana seorang siswa kelas 6 mengamalkan adab Islami ketika melihat perdebatan panas dan ujaran kebencian di kolom komentar internet?', ['Ikut memaki dan menambah panas suasana menggunakan kata-kata kasar', 'Tidak terpancing emosi, menahan diri dari berkomentar buruk, atau menyebarkan pesan perdamaian yang menyejukkan hati', 'Membuat akun palsu untuk menyerang lawan debat', 'Menyebarkan hoaks agar suasana semakin ramai'], 1, 'Adab digital muslim mencakup menjaga lisan jemari dari fitnah dan mengedepankan perkataan yang menyejukkan (qaulan layyina).');
addQ(6, 'sulit', 'Filosofi Lempar Jumrah', 'Ritual melempar jumrah (Ula, Wustha, Aqabah) dengan kerikil di Mina saat pelaksanaan haji melambangkan tekad manusia untuk ...', ['Membuang batu-batu kerikil yang berserakan di jalan', 'Memerangi, melempar, dan menundukkan bujuk rayu godaan iblis yang berusaha menyesatkan manusia dari jalan Allah', 'Melatih ketepatan membidik mangsa berburu', 'Menghancurkan bangunan kuno di padang pasir'], 1, 'Melempar jumrah meneladani Nabi Ibrahim saat mengusir godaan setan yang membujuknya agar tidak taat pada perintah Allah.');
addQ(6, 'sulit', 'Kajian Sifat Allah Al-Ghaffar', 'Perbedaan antara sifat Allah Al-Ghaffar dengan sifat pemaaf manusia adalah bahwa ampunan Allah ...', ['Terbatas hanya untuk orang-orang tertentu saja', 'Maha Luas meliputi seluruh dosa hamba yang bertaubat dengan tulus, tanpa ada rasa dendam atau pamrih', 'Membutuhkan tebusan uang emas yang banyak', 'Hanya diberikan pada hari raya Idul Fitri saja'], 1, 'Al-Ghaffar bermakna ampunan Allah tiada bertepi bagi hamba yang memohon ampun dengan sungguh-sungguh.');
addQ(6, 'sulit', 'Menjaga Hubungan Baik Antar Tetangga', 'Rasulullah SAW bersabda: "Malaikat Jibril terus-menerus berwasiat kepadaku tentang hak-hak tetangga, hingga aku menyangka bahwa tetangga itu akan ..."', ['Diberi hak warisan harta keluarga', 'Diusir dari kampung halaman', 'Dilarang keluar rumah di waktu malam', 'Dikenakan denda harian'], 0, 'Saking tingginya penghormatan dan hak tetangga dalam Islam, Nabi mengira tetangga akan mendapat bagian harta waris.');
addQ(6, 'sulit', 'Tuntunan Menghadapi Kematian', 'Ketika mendampingi orang yang sedang sakaratul maut, tuntunan sunnah Rasulullah adalah mentalqinkannya dengan kalimat tauhid yang lembut yaitu ...', ['Alhamdulillah', 'Laa ilaaha illallaah', 'Subhanallah', 'Allahu Akbar dengan suara berteriak'], 1, 'Nabi bersabda: "Talqinkanlah orang yang hendak wafat di antara kalian dengan kalimat Laa ilaaha illallaah."');
addQ(6, 'sulit', 'Analisis Dam (Denda) Haji', 'Apa yang dimaksud dengan "Dam" dalam pelaksanaan ibadah haji?', ['Denda atau tebusan (seperti menyembelih kambing atau berpuasa) bagi jamaah yang melanggar larangan ihram atau meninggalkan kewajiban haji', 'Uang tiket pesawat terbang pulang pergi', 'Hadiah piala bagi jamaah yang tercepat sa\'i', 'Pajak hotel di sekitar Masjidil Haram'], 0, 'Dam adalah sanksi kafarat/denda syar\'i berupa kurban atau puasa karena melanggar larangan ihram atau meninggalkan wajib haji.');
addQ(6, 'sulit', 'Hakikat Kemenangan Idul Fitri', 'Makna hakiki "kembali kepada fitrah" pada hari raya Idul Fitri setelah berpuasa sebulan penuh adalah ...', ['Memakai baju baru dan memamerkan perhiasan', 'Kembali kepada kesucian jiwa laksana bayi baru lahir karena dosa-dosanya telah diampuni oleh Allah SWT', 'Makan makanan lezat sepuasnya tanpa batas', 'Berhenti beribadah karena bulan Ramadhan telah berakhir'], 1, 'Idul Fitri adalah hari raya kesucian jiwa bagi mereka yang berhasil melatih ketakwaan dan meraih ampunan Ilahi.');
addQ(6, 'sulit', 'Mewujudkan Keadilan Sosial', 'Bagaimana keterkaitan antara rukun iman dan rukun Islam dalam membentuk masyarakat yang adil dan beradab?', ['Rukun iman adalah fondasi keyakinan batin, sedangkan rukun Islam adalah amalan nyata yang mendidik kedisiplinan dan solidaritas sosial', 'Keduanya tidak memiliki keterkaitan sama sekali', 'Cukup mengamalkan rukun iman saja tanpa perlu rukun Islam', 'Hanya berguna saat belajar pelajaran agama di kelas'], 0, 'Iman adalah akar keyakinan batin yang melahirkan cabang-cabang amal ibadah dan akhlak sosial luhur di tengah masyarakat.');
addQ(6, 'sulit', 'Meneladani Kezuhudan Khulafaur Rasyidin', 'Sahabat Khalifah Umar bin Khattab r.a. berkeliling malam hari memikul sendiri gandum untuk memasak bagi seorang ibu dan anak-anaknya yang kelaparan. Nilai luhur kepemimpinan yang dapat diteladani adalah ...', ['Pemimpin harus memiliki pengawal pribadi bersenjata lengkap', 'Pemimpin adalah pelayan rakyat yang memikul tanggung jawab moral langsung atas kesejahteraan warganya', 'Pemimpin hanya perlu membagikan makanan saat kampanye pemilihan', 'Tugas pemimpin cukup duduk santai di dalam istana mewah'], 1, 'Kepemimpinan dalam Islam adalah amanah pengabdian melayani rakyat dengan kerendahan hati dan empati nyata.');
addQ(6, 'sulit', 'Hikmah Tahallul Haji', 'Memotong rambut pada saat tahallul haji melambangkan pembersihan diri dari ...', ['Kutu rambut yang menempel di kepala', 'Sifat-sifat buruk, dosa-dosa pikiran yang kotor, dan membuka lembaran baru yang suci', 'Kerapian gaya rambut agar difoto bagus', 'Tradisi memanjangkan rambut kembali di tahun depan'], 1, 'Tahallul secara simbolis mencukur kesombongan intelektual, pikiran kotor, dan menyucikan mahkota kepala manusia.');
addQ(6, 'sulit', 'Keseimbangan Doa Dunia Akhirat', 'Doa sapu jagad "Rabbana aatina fid-dunya hasanah wa fil aakhirati hasanah wa qina \'adzaaban-naar" mengajarkan prinsip hidup muslim yaitu ...', ['Hanya mengejar harta kekayaan dunia tanpa memikirkan akhirat', 'Keseimbangan antara meraih kebahagiaan hidup di dunia yang berkah dan keselamatan abadi di akhirat kelak', 'Meninggalkan seluruh urusan dunia dan hidup menyendiri di hutan', 'Hanya berdoa saat mendapatkan musibah saja'], 1, 'Islam mengajarkan keseimbangan proporsional: meraih kesuksesan duniawi yang halal demi menggapai kemuliaan akhirat.');
addQ(6, 'sulit', 'Menjaga Kemurnian Al-Qur\'an', 'Allah SWT berfirman dalam Surat Al-Hijr ayat 9: "Inna nahnu nazzalnadz-dzikra wa inna lahu lahaafizhuun". Maksud jaminan Allah dalam ayat ini adalah ...', ['Mushaf Al-Qur\'an tidak boleh dicetak oleh manusia', 'Allah sendiri yang menjamin pemeliharaan kemurnian Al-Qur\'an dari segala perubahan, pemalsuan, dan penambahan hingga akhir zaman', 'Al-Qur\'an hanya tersimpan di langit saja', 'Setiap orang bebas mengubah terjemahan Al-Qur\'an sesuai selera pribadi'], 1, 'Kemurnian Al-Qur\'an dijamin langsung oleh Allah SWT melalui jutaan penghafal (huffadz) di seluruh dunia sepanjang zaman.');

fs.writeFileSync(path.join(__dirname, '..', 'generators', 'agama_islam.json'), JSON.stringify(islamQuestions, null, 2), 'utf8');
